from pathlib import Path

source_path = Path(__file__).with_name("_pcna_app_source.py")
source = source_path.read_text(encoding="utf-8")

# Replace the legacy home-only sizing layer wholesale with one responsive mobile shell.
# The four-card grid receives the remaining usable viewport height instead of relying on
# guessed card heights. Global scrolling stays enabled as a failsafe on unusually short
# screens or when accessibility/browser chrome increases the required content height.
start_marker = '''if page == "home":\n    st.markdown(\n        """\n<style>\n'''
end_marker = '''\n""",\n        unsafe_allow_html=True,\n    )\n\napproved_pcna_header(98 if page == "home" else 105)'''

start = source.index(start_marker)
end = source.index(end_marker, start) + len(end_marker)

home_layout = '''if page == "home":\n    st.markdown(\n        """\n<style>\n/* HOME — single responsive phone-first layout. */\n:root {\n  --home-nav-height: 76px;\n  --home-gap: 9px;\n}\n\nhtml,\nbody,\n[data-testid="stAppViewContainer"] {\n  width: 100%;\n  min-height: 100%;\n  overflow-x: hidden !important;\n  overflow-y: auto !important;\n}\n\n[data-testid="stAppViewContainer"] > .main {\n  width: 100%;\n  min-height: 100dvh !important;\n  height: auto !important;\n  overflow-x: hidden !important;\n  overflow-y: auto !important;\n}\n\n.block-container {\n  width: 100% !important;\n  max-width: 620px !important;\n  height: calc(100dvh - var(--home-nav-height) - env(safe-area-inset-bottom)) !important;\n  min-height: 560px !important;\n  box-sizing: border-box !important;\n  margin: 0 auto !important;\n  padding: calc(6px + env(safe-area-inset-top)) 10px 8px !important;\n  overflow: visible !important;\n}\n\n/* One vertical application shell: logo → hero → heading → flexible card grid. */\n.block-container > [data-testid="stVerticalBlock"] {\n  display: flex !important;\n  flex-direction: column !important;\n  width: 100% !important;\n  height: 100% !important;\n  min-height: 0 !important;\n  gap: 0 !important;\n  overflow: visible !important;\n}\n\n.block-container [data-testid="stVerticalBlock"],\n.block-container [data-testid="stElementContainer"] {\n  min-height: 0 !important;\n}\n\n/* Approved PCNA logo stays untouched; only wrapper whitespace is reduced. */\n[data-testid="stImage"] {\n  margin: 0 0 2px !important;\n  padding: 0 !important;\n  overflow: visible !important;\n}\n[data-testid="stImage"] img {\n  display: block !important;\n  margin: 0 auto !important;\n  max-width: 100% !important;\n  height: auto !important;\n  object-fit: contain !important;\n}\n\n/* Keep the existing hero, but stop it from consuming too much of short phone screens. */\n.block-container [data-testid="stElementContainer"]:has(iframe[title="streamlit_component"]) {\n  flex: 0 0 auto !important;\n  height: auto !important;\n  min-height: 0 !important;\n  margin: 0 !important;\n  overflow: visible !important;\n}\niframe[title="streamlit_component"] {\n  display: block !important;\n  width: 100% !important;\n  height: clamp(120px, 17.5dvh, 150px) !important;\n  min-height: 0 !important;\n  margin: 0 !important;\n}\n\n.section-title {\n  flex: 0 0 auto !important;\n  font-size: 19px !important;\n  line-height: 1.08 !important;\n  margin: 5px 0 6px !important;\n}\n\n/* This wrapper consumes the exact space left after the logo, hero and heading. */\n.block-container > [data-testid="stVerticalBlock"] > [data-testid="stElementContainer"]:has(.action-grid) {\n  flex: 1 1 0 !important;\n  height: auto !important;\n  min-height: 0 !important;\n  margin: 0 !important;\n  overflow: visible !important;\n}\n.block-container > [data-testid="stVerticalBlock"] > [data-testid="stElementContainer"]:has(.action-grid) > div {\n  width: 100% !important;\n  height: 100% !important;\n  min-height: 0 !important;\n}\n\n.action-grid {\n  display: grid !important;\n  grid-template-columns: repeat(2, minmax(0, 1fr)) !important;\n  grid-template-rows: repeat(2, minmax(0, 1fr)) !important;\n  width: 100% !important;\n  height: 100% !important;\n  min-height: 0 !important;\n  gap: var(--home-gap) !important;\n  margin: 0 !important;\n  padding: 0 0 2px !important;\n  box-sizing: border-box !important;\n  align-items: stretch !important;\n}\n\n.action-card {\n  display: flex !important;\n  flex-direction: column !important;\n  justify-content: center !important;\n  width: 100% !important;\n  height: 100% !important;\n  min-width: 0 !important;\n  min-height: 0 !important;\n  box-sizing: border-box !important;\n  padding: clamp(10px, 2.2dvh, 15px) 12px !important;\n  border-radius: 15px !important;\n  overflow: hidden !important;\n}\n.action-icon {\n  flex: 0 0 auto !important;\n  font-size: clamp(20px, 2.8dvh, 24px) !important;\n  line-height: 1 !important;\n  margin: 0 0 5px !important;\n}\n.action-title {\n  flex: 0 0 auto !important;\n  font-size: clamp(15px, 2.05dvh, 17px) !important;\n  line-height: 1.08 !important;\n  margin: 0 0 4px !important;\n}\n.action-copy {\n  flex: 0 1 auto !important;\n  font-size: clamp(10.5px, 1.42dvh, 12px) !important;\n  line-height: 1.2 !important;\n  margin: 0 !important;\n}\n\n/* Bottom navigation remains fixed; the shell explicitly reserves its full height. */\n.bottom-nav {\n  height: var(--home-nav-height) !important;\n  padding-bottom: max(7px, env(safe-area-inset-bottom)) !important;\n}\n\n/* Slightly taller screens can breathe without changing the 2×2 structure. */\n@media (min-height: 900px) and (max-width: 620px) {\n  :root { --home-gap: 11px; }\n  .block-container { padding-top: calc(9px + env(safe-area-inset-top)) !important; }\n  .section-title { margin-top: 7px !important; margin-bottom: 8px !important; }\n}\n\n/* Short phone fallback: preserve the same layout and allow the document to scroll. */\n@media (max-height: 650px) and (max-width: 620px) {\n  .block-container {\n    height: auto !important;\n    min-height: calc(100dvh - var(--home-nav-height) - env(safe-area-inset-bottom)) !important;\n    padding-bottom: 10px !important;\n  }\n  .block-container > [data-testid="stVerticalBlock"] {\n    height: auto !important;\n    min-height: calc(100dvh - var(--home-nav-height) - env(safe-area-inset-bottom) - 16px) !important;\n  }\n  iframe[title="streamlit_component"] {\n    height: 112px !important;\n  }\n  .action-grid {\n    min-height: 230px !important;\n  }\n}\n\n/* Tablet/desktop: preserve the same cards and navigation without breaking phone behavior. */\n@media (min-width: 621px) {\n  .block-container {\n    height: auto !important;\n    min-height: calc(100dvh - var(--home-nav-height)) !important;\n    padding: calc(16px + env(safe-area-inset-top)) 15px calc(94px + env(safe-area-inset-bottom)) !important;\n  }\n  .block-container > [data-testid="stVerticalBlock"] {\n    height: auto !important;\n  }\n  .block-container > [data-testid="stVerticalBlock"] > [data-testid="stElementContainer"]:has(.action-grid) {\n    flex: 0 0 auto !important;\n  }\n  .block-container > [data-testid="stVerticalBlock"] > [data-testid="stElementContainer"]:has(.action-grid) > div,\n  .action-grid {\n    height: auto !important;\n  }\n  .action-grid {\n    grid-template-rows: repeat(2, minmax(120px, auto)) !important;\n    gap: 12px !important;\n  }\n  .action-card {\n    min-height: 120px !important;\n  }\n}\n</style>\n""",\n        unsafe_allow_html=True,\n    )\n\napproved_pcna_header(98 if page == "home" else 105)'''

source = source[:start] + home_layout + source[end:]

exec(compile(source, str(source_path), "exec"), globals(), globals())
